from g_common import *
from g_desk import PRIO_WIDGET, NOTE_CHOOSER

NAV = [("Service Board", "Every ticket on your boards, worst clock first. Shortcut g then b."), ("Dispatch", "The unrouted queue, today's visits and who answers each board. Shortcut g then d."),
       ("Schedule", "The week by person, with the In / out word under each name."), ("Calendar", "Your calendar, or a colleague's, with a feed for your phone."),
       ("Timesheets", "Your week of time, submitted for approval."), ("Projects", "Planned work in phases."), ("Knowledge", "Fixes written once and used again."),
       ("Companies", "Companies, contacts and configurations. Shortcut g then c."), ("On-call", "Who is on call now and next, and pages."),
       ("Reports", "The service in numbers, and your own reports."), ("Finance", "Agreements and BizBox's purchase orders, products and invoices."),
       ("Sales", "Opportunities, quotes and the pipeline."), ("Uplift", "The evidence of the service's hours and work."), ("Setup", "Boards, members, roles, rules and setup tables. Shortcut g then s.")]


def staff_body():
    pick = ('<div class="pick" role="group" aria-label="Who are you?">'
            '<button data-role="R" aria-pressed="false"><div class="dot" style="background:var(--green)"><svg><use href="#i-user"/></svg></div><b>I work on a ward or in an office</b><span>Ask for help, follow your request, approve, read Help.</span></button>'
            '<button data-role="T" aria-pressed="false"><div class="dot" style="background:var(--blue)"><svg><use href="#i-wrench"/></svg></div><b>I am a technician</b><span>The board, tickets, visits, time, knowledge.</span></button>'
            '<button data-role="M" aria-pressed="false"><div class="dot" style="background:var(--blue-l)"><svg><use href="#i-chart"/></svg></div><b>I manage the service</b><span>On-call, reports, approvals, projects, finance and sales.</span></button>'
            '<button data-role="A" aria-pressed="false"><div class="dot" style="background:var(--orange)"><svg><use href="#i-gear"/></svg></div><b>I set the desk up</b><span>Boards, members, roles, rules, email, audit.</span></button></div>')
    navmap = WIDGET("Click an area to see what it is for", OPTS([(n, n) for n, _ in NAV], attr="data-k").replace('data-k="', 'data-t-k="')
                    + '<div class="w-out out">Click an area above.</div>', "chooser")
    for n, t in NAV:
        navmap = navmap.replace(f'data-t-k="{E(n)}"', f'data-t="{E(t)}"')
    return "".join([
        HERO("Dada PSA, the PMC service desk", "How to ask Dada IT for help, and how Dada IT works every request. This guide is the overview; the module guides below go deep into each area, each with its own interactive tools.",
             ["For every PMC staff member", "14 guides", "Works offline, prints cleanly"]),
        pick,
        S("library", "Start here", "All the guides",
          LEAD("One guide per area of the desk. Each opens in your browser, works offline, and has its own try-it tools and a short check at the end."),
          LIBRARY("Staff"), who=["Everyone"], roles="R T M A"),
        S("start", "Start here", "What Dada PSA is",
          LEAD("Dada PSA is where every IT request at PMC lives. It has two doors: PMC Requests for the people who ask, and the desk for Dada IT."),
          GRID([("PMC Requests", "For every staff member, at <code>help.pmcne.ph</code> or through the Employee Portal. You see only your own requests."),
                ("The desk", "For Dada IT, at <code>desk.pmcne.ph</code>, signed in with Microsoft. Every request lands on a board with a number, a priority and running clocks.")]),
          NOTE("warn", "<b>Never write a patient's details.</b> Not in a request, a note, an email reply, an article or a file name. The ward, the room and the machine are all Dada IT ever needs."),
          STEPS(["<b>It arrives</b> from PMC Requests, an email, a phone call or a monitoring system.", "<b>It lands on a board</b> with a number, a status, a contact and a priority from two plain questions.",
                 "<b>The clocks start:</b> Respond, Resolution plan, Resolve.", "<b>Someone owns it</b>, writes notes, books a visit if needed, records time.", "<b>It is resolved and closed</b>, and the requester is asked how we did."]),
          who=["Everyone"], roles="R T M A"),
        S("raise", "Asking for help", "Raise a request", TOUR("portal"), PRIO_WIDGET,
          P(f'More in the <a href="{fname("PMC_Requests")}">PMC Requests guide</a>.'), who=["Ward staff"], roles="R T"),
        S("follow", "Asking for help", "Follow, add to and approve requests",
          FIG("portal-request", "A request on PMC Requests."),
          UL(["Add a note or photo, or reply to the email keeping the reference in the subject.", "Emails never carry the details.", "Approvals come to your department's approver under Approvals; a decline must say why."]),
          who=["Ward staff", "Approvers"], roles="R M"),
        S("desk", "Working the desk", "Find your way around", navmap,
          TABLE(["Keys", "What it does"], [["<kbd>Ctrl</kbd> <kbd>K</kbd>", "Jump to a page or ticket."], ["<kbd>n</kbd>", "New ticket."], ["<kbd>g</kbd> then <kbd>b</kbd> <kbd>d</kbd> <kbd>c</kbd> <kbd>s</kbd>", "Board, Dispatch, Companies, Setup."],
                                           ["<kbd>j</kbd> <kbd>k</kbd> <kbd>x</kbd> <kbd>Enter</kbd>", "Move, tick and open rows."], ["<kbd>/</kbd> <kbd>t</kbd> <kbd>?</kbd>", "Search, theme, all shortcuts."]]),
          who=["Technicians", "Managers"], roles="T M A"),
        S("board", "Working the desk", "The board and a ticket", TOUR("board"), TOUR("ticket"), NOTE_CHOOSER,
          P(f'More in the <a href="{fname("Service_Desk")}">Service Desk guide</a> and the <a href="{fname("Dispatch_OnCall")}">Dispatch and On-call guide</a>.'),
          who=["Technicians"], roles="T M"),
        S("phone", "Working the desk", "On your phone",
          LEAD("Nothing to install. Open the desk in your phone's browser: the board becomes cards, and a ticket has Note, Ticket and Call at your thumb."),
          '<div class="phones">' + FIG("phone-board", "The board as cards.") + FIG("phone-ticket", "A ticket, with Call dialling the contact.") + "</div>",
          who=["Technicians"], roles="T"),
        S("day", "Your day", "Schedule, Dispatch and In / out",
          LEAD("Schedule is the week by person. Dispatch is today. In / out is the board by the door."),
          FIG("schedule", "Schedule: each person's week; the word under a name comes from In / out."),
          UL(["<b>Book a visit</b> from the ticket's Schedule card or under the week; the desk warns of a double booking.", "<b>Time off, a meeting or an activity</b> goes in the same week.", "<b>Dispatch</b> shows today's visits and what nobody owns yet."]),
          FIG("inout", "In / out: In, Out, On site, Working remotely or On leave, a note and when you are back."),
          P(f'More in the <a href="{fname("Scheduling")}">Scheduling guide</a> and the <a href="{fname("Dispatch_OnCall")}">Dispatch and On-call guide</a>.'),
          who=["Technicians", "Managers"], roles="T M"),
        S("calendar", "Your day", "Calendar and your profile",
          FIG("calendar", "Calendar: visits, time off, meetings and on-call shifts."),
          STEPS(["<b>Open My profile</b> from your name.", "<b>Press Make a feed address</b> and copy it.", "<b>Add it to your phone's calendar.</b> It names tickets and places, never what a ticket says."]),
          FIG("profile", "My profile: what the desk holds on you, your phone numbers, and the calendar feed."),
          who=["Technicians", "Managers"], roles="T M"),
        S("time", "Your day", "Time and timesheets",
          FIG("time", "Timesheets: your week, submitted for approval."),
          STEPS(["<b>On the ticket</b>, add time: start and end, or hours, with the work role and type.", "<b>On Timesheets</b>, check the week and press Submit.", "<b>Your approver</b> approves it or rejects it with a reason."]),
          P(f'Try the time calculator in the <a href="{fname("Time")}">Time guide</a>.'), who=["Technicians", "Managers"], roles="T M"),
        S("kb", "Knowing things", "Knowledge base",
          FIG("kb", "Knowledge, filtered by category."), FIG("kb-article", "An article."),
          P(f'Write, publish and see who sees what in the <a href="{fname("Knowledge")}">Knowledge guide</a>.'), who=["Technicians", "Managers"], roles="T M A"),
        S("companies", "Knowing things", "Companies and configurations",
          FIG("company", "A company: status and type, open tickets, contacts, configurations."),
          FIG("configuration", "A configuration: its life, its questions, every ticket about it."),
          P(f'More in the <a href="{fname("Companies_Configurations")}">Companies and Configurations guide</a>.'), who=["Technicians"], roles="T M A"),
        S("oncall", "Running the service", "On-call and paging",
          FIG("oncall", "On-call: who is on call now, and the rota."),
          P(f'A page repeats every 5 minutes, 3 times, then goes to the duty manager. Try it in the <a href="{fname("Dispatch_OnCall")}">Dispatch and On-call guide</a>.'),
          who=["Managers", "Technicians"], roles="M T"),
        S("reports", "Running the service", "Reports and projects",
          FIG("reports", "Reports: volumes, clocks met, satisfaction, utilisation."), FIG("projects", "Projects with budget against actual."),
          P(f'More in the <a href="{fname("Reports")}">Reports guide</a> and the <a href="{fname("Projects")}">Projects guide</a>.'), who=["Managers"], roles="M"),
        S("money", "Running the service", "Finance and sales",
          FIG("fin-procurement", "Finance: BizBox's purchase orders beside the work, read-only."),
          FIG("sales", "Sales: the pipeline by stage."),
          GRID([("Finance", f'Agreements, BizBox records, linking money to work, proposing changes, and the planned two-way BizBox link. <a href="{fname("Finance")}">Finance guide</a>'),
                ("Sales", f'Opportunities, quotes and the weighted pipeline. <a href="{fname("Sales")}">Sales guide</a>')]),
          who=["Managers"], roles="M"),
        S("setup", "Setting up", "Setup at a glance",
          FIG("admin", "Setup: the cards you may open."),
          FIG("board-emails", "A board's Emails tab: the board's own words, four placeholders only."),
          FIG("board-assign", "A board's Auto-assign tab."),
          P(f'Every page, with try-it tools for rules, roles, emails and auto-assign, is in the <a href="{fname("Setup")}">Setup and Administration guide</a>. Changes are in the <a href="{fname("Change")}">Change management guide</a>.'),
          who=["Administrators"], roles="A"),
        S("faq", "Reference", "Questions people ask",
          DET([("I cannot see a request my colleague raised.", "PMC Requests shows each person only their own."),
               ("My request is urgent but shows P4.", "Add a note saying what changed, or phone the desk; a technician can change the answers."),
               ("It was closed but is still broken.", "Reply to the closing email: most boards reopen it."),
               ("A board is missing from my list.", "Ask its administrator to add you on Members & roles."),
               ("Can I delete a ticket or a note?", "No. Duplicates are merged, mistakes are corrected with a new note.")]), who=["Everyone"], roles="R T M A"),
        S("glossary", "Reference", "Words the desk uses",
          GRID([("Board", "A queue of work for one team."), ("Ticket", "One request, numbered PMC-000123."), ("Priority", "P1 to P4, from two questions. Never typed."),
                ("SLA clocks", "Respond, Resolution plan, Resolve, on the board's working hours."), ("Subtype › Item", "What the ticket is about: Printer › Failure."),
                ("Discussion note", "The requester can read it."), ("Internal note", "The desk only."), ("Resolution note", "How it was fixed."),
                ("Configuration", "A machine the desk looks after."), ("Restricted board", "Members only; every read audited."), ("Page", "An urgent call, repeated until answered."),
                ("BizBox", "PMC's finance system; the desk reads a copy.")]), who=["Everyone"], roles="R T M A"),
        S("quiz", "Reference", "Check yourself", QUIZ(), who=["Everyone"], roles="R T M A"),
    ])


GUIDES.insert(0, {"slug": "Staff", "title": "Staff guide (start here)", "for": "everyone", "kind": "req",
    "blurb": "The overview for every PMC staff member, and the way in to every module guide.",
    "rail_sub": "Staff guide · September 2026", "search": "Search the guide: ticket, survey, timesheet…", "body": staff_body, "chips": True,
    "tours": {},
    "quiz": [["A nurse wants to add that the printer now also jams. Where?", ["A second request", "A note on the request, or a reply to the email"], 1, "Keep it on the same request."],
             ["Which note stays on the desk?", ["Discussion", "Internal", "Resolution"], 1, "Internal notes are never emailed or shown."],
             ["One nurse, no patient waiting. Priority?", ["P3", "P4"], 1, "Just me and no one waiting is P4."],
             ["What may a request say about a patient?", ["Initials", "Nothing"], 1, "Ward, room and machine are enough."]]})
